method FindFirstRepeatedChar(s: string) returns (result: char?, isUnique: bool)
  // Postcondition: If a character is found, it is the first character in the string
  // that is unique (appears exactly once) in the entire string.
  ensures result != null ==> (
    // The character exists in the string
    exists i: int :: 0 <= i < |s| && s[i] == result &&
    // It appears exactly once
    (forall j: int :: 0 <= j < |s| && s[j] == result ==> i == j) &&
    // It is the first such character
    (forall k: int :: 0 <= k < i ==> exists l: int :: 0 <= l < |s| && l != k && s[l] == s[k])
  )
  ensures result == null ==> (
    // No character appears exactly once
    forall i: int :: 0 <= i < |s| ==> exists j: int :: 0 <= j < |s| && j != i && s[j] == s[i]
  )
  ensures isUnique == (result != null)
{
  // Initialize result to null (no character found)
  result := null;
  isUnique := false;

  var n := |s|;
  if n == 0 {
    return;
  }

  // First pass: count occurrences of each character
  var charCounts := new int[256]; // Assuming ASCII characters
  var idx := 0;

  while idx < n
    invariant 0 <= idx <= n
    invariant forall ch: int :: 0 <= ch < 256 ==> 
      charCounts[ch] == |{k: int | 0 <= k < idx && ord(s[k]) == ch}|
  {
    var ch := ord(s[idx]);
    if 0 <= ch < 256 {
      charCounts[ch] := charCounts[ch] + 1;
    }
    idx := idx + 1;
  }

  // Second pass: find first character with count == 1
  idx := 0;
  while idx < n && result == null
    invariant 0 <= idx <= n
    invariant result == null ==> 
      forall k: int :: 0 <= k < idx ==> charCounts[ord(s[k])] != 1
    invariant result != null ==> (
