      charCounts[ord(result)] == 1 &&
      (forall k: int :: 0 <= k < i ==> charCounts[ord(s[k])] != 1)
    )
  {
    var ch := s[idx];
    var chCode := ord(ch);
    if 0 <= chCode < 256 && charCounts[chCode] == 1 {
      result := ch;
      isUnique := true;
    }
    idx := idx + 1;
  }
}
