          j := j + 1;
        }
        newWords[words.Length] := current;
        words := newWords;
        current := "";
      }
    } else {
      current := current + [ch];
    }
    i := i + 1;
  }

  if |current| > 0 {
    // Create new array for final word
    var newSize := words.Length + 1;
    var newWords: array<string>;
    newWords := new string[newSize];
    var j := 0;
    while j < words.Length {
      newWords[j] := words[j];
      j := j + 1;
